insert into vanta_demo_products values
  ('b932484c-98fb-f6a4-4bf3-b4131a97fd10', 'remeras', 'Remera Essential — DEMO', 'vanta-demo-remera-essential', 'Remera de algodón de corte amplio, cuello redondo y terminaciones limpias. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 2500000),
  ('a407d197-84d3-02f7-d5bb-10cea8e7483a', 'remeras', 'Remera Box — DEMO', 'vanta-demo-remera-box', 'Remera de silueta boxy en algodón pesado, con bolsillo discreto en el pecho. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 2900000),
  ('287d20bb-02b0-7abf-1ed1-5faeb2bde79d', 'buzos', 'Buzo Core — DEMO', 'vanta-demo-buzo-core', 'Buzo con capucha, bolsillo canguro y calce amplio para superponer capas. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 5500000),
  ('592bb001-2877-5fba-c58f-8f9dd7befd29', 'buzos', 'Buzo Relax — DEMO', 'vanta-demo-buzo-relax', 'Buzo de cuello redondo, hombros caídos y puños acanalados. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 4900000),
  ('5361ea09-80a3-470e-93c6-8de3e87c4ee8', 'pantalones', 'Pantalón Forma — DEMO', 'vanta-demo-pantalon-forma', 'Pantalón urbano de pierna amplia y líneas de sastrería relajada. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 4800000),
  ('3d805548-7c4b-949b-8922-3e59ca73b1c1', 'pantalones', 'Pantalón Cargo — DEMO', 'vanta-demo-pantalon-cargo', 'Pantalón de corte relajado con bolsillos utilitarios y terminaciones sobrias. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 5200000),
  ('be4c0686-4506-4b1c-c4e5-a8bdb8105c87', 'conjuntos', 'Conjunto Studio — DEMO', 'vanta-demo-conjunto-studio', 'Conjunto de campera con cierre y pantalón recto, de estética monocromática. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 8000000),
  ('d07af362-15e2-07a1-92db-590b75aa612b', 'conjuntos', 'Conjunto Weekend — DEMO', 'vanta-demo-conjunto-weekend', 'Conjunto de buzo de cuello redondo y jogger amplio para todos los días. Producto y precio ficticios para revisión de VANTA. Fotografía original generada con IA; ilustrativa del modelo y no de todas las variantes de color. No constituye una oferta comercial.', 7600000);
